import{_ as a,o as n,c as i,ai as e}from"./chunks/framework.XEs52zTF.js";const k=JSON.parse('{"title":"编译到栈式字节码","description":"","frontmatter":{"title":"编译到栈式字节码","chapterId":"chapter11","prev":{"text":"名字、作用域与类型","link":"/chapter10"},"next":{"text":"让程序真正跑起来","link":"/chapter12"}},"headers":[],"relativePath":"chapter11.md","filePath":"chapter11.md"}'),p={name:"chapter11.md"};function l(t,s,r,h,d,c){return n(),i("div",null,[...s[0]||(s[0]=[e(`<h1 id="_11-从语法树到字节码-第一次真正生成程序" tabindex="-1">11 从语法树到字节码：第一次真正生成程序 <a class="header-anchor" href="#_11-从语法树到字节码-第一次真正生成程序" aria-label="Permalink to &quot;11 从语法树到字节码：第一次真正生成程序&quot;">​</a></h1><h2 id="学习目标与前置知识" tabindex="-1">学习目标与前置知识 <a class="header-anchor" href="#学习目标与前置知识" aria-label="Permalink to &quot;学习目标与前置知识&quot;">​</a></h2><p>你已经能把源码读成 AST，并检查名字和类型。本章要把树变成一列可以检查、保存和执行的指令。完成后，你应能手工编译表达式、分支、循环和短路逻辑，检查每条路径上的栈是否平衡。前置是第 7、9、10 章的递归遍历、变量绑定和类型规则。</p><p>本章属于<strong>可运行主线</strong>：配套编译器确实包含字节码生成器和虚拟机。下面大写指令是教学记法，不是对实际输出格式的逐字复制；请用 <code>sprout --bytecode 文件</code> 查看真实指令。教学片段旨在推导算法，不能直接覆盖参考工程里的同名函数。</p><h2 id="为什么不直接执行语法树" tabindex="-1">为什么不直接执行语法树 <a class="header-anchor" href="#为什么不直接执行语法树" aria-label="Permalink to &quot;为什么不直接执行语法树&quot;">​</a></h2><p>AST 保留“这是乘法”“这是 while”等源语言结构。直接递归执行它也能构成解释器，但每次运行都需要访问节点类别和子节点。字节码提前把结构翻译成简单动作：读常数、取变量、算术、跳转、调用。执行器只需按照程序计数器逐条处理。</p><p>这里已经发生了编译：输入是 Sprout 程序，输出是另一套指令集的程序。VM 解释执行目标指令，并不否定前面的编译过程。以后换成 C++、LLVM IR 或本机指令时，词法、语法和语义前端仍可复用。第一台目标机器选择简单、容易观察的栈机，可以减少同时学习新概念的负担。</p><h2 id="先设计计算栈" tabindex="-1">先设计计算栈 <a class="header-anchor" href="#先设计计算栈" aria-label="Permalink to &quot;先设计计算栈&quot;">​</a></h2><p>栈是一叠只能从顶部取放的值。PUSH 压值；二元运算先弹右操作数、再弹左操作数，将结果压回。表达式 <code>3 + 4 * 2</code> 对应树的后序遍历：先左子树 3，再右子树乘法，最后加法。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>指令        执行后的栈，右端是栈顶</span></span>
<span class="line"><span>PUSH 3      [3]</span></span>
<span class="line"><span>PUSH 4      [3, 4]</span></span>
<span class="line"><span>PUSH 2      [3, 4, 2]</span></span>
<span class="line"><span>MUL         [3, 8]</span></span>
<span class="line"><span>ADD         [11]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>减法最能暴露操作数顺序问题：栈为 [8,2] 时 SUB 应得到 6。仅测加法与乘法不够，因为交换律会掩盖错误。除法和比较也必须保持同样的左右关系。</p><p>给每条指令写一份栈效果表：常数和 LOAD 净增一；STORE、PRINT 净减一；二元算术净减一；一元取负不改变高度。表达式编译前后的高度差应为一，普通语句应为零，return 把结果交回调用者。这组不变量可用于自动校验，比“样例能跑”更可靠。</p><h2 id="用槽位代替名字" tabindex="-1">用槽位代替名字 <a class="header-anchor" href="#用槽位代替名字" aria-label="Permalink to &quot;用槽位代替名字&quot;">​</a></h2><p>前端已经区分了不同的变量绑定。参考实现的 Checker 在语义检查时给每个绑定分配一个整数槽位，代码生成器直接沿用，例如 main 的 x 是 0，内层块另一个 x 是 1。LOAD 0 读取当前函数帧的第 0 个槽位。生成器应使用前端解析出的绑定身份，不能再仅靠字符串重新查名，否则遮蔽关系容易丢失。</p><p>将下面程序保存为 <code>lesson11.sprout</code>：</p><div class="language-sprout vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sprout</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">fn</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> main</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> x </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(x);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sprout --check lesson11.sprout</span></span>
<span class="line"><span>sprout --bytecode lesson11.sprout</span></span>
<span class="line"><span>sprout lesson11.sprout</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Windows 使用实际的 sprout.exe 路径。运行应输出 11。dump 中应出现三个常数、先乘后加、存变量、读变量、打印和返回。地址可能随实现调整，验收重点是依赖关系和顺序。</p><h2 id="分支-先留空-再回填" tabindex="-1">分支：先留空，再回填 <a class="header-anchor" href="#分支-先留空-再回填" aria-label="Permalink to &quot;分支：先留空，再回填&quot;">​</a></h2><p>编译 if 时，生成条件后尚不知道 else 从哪个地址开始。先发出一个目标待定的跳转，记录它在数组中的位置；then 编译完后，回填目标。then 末尾还需无条件跳转，越过 else。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LOAD x</span></span>
<span class="line"><span>PUSH 5</span></span>
<span class="line"><span>LT</span></span>
<span class="line"><span>JUMP_IF_FALSE else_begin</span></span>
<span class="line"><span>PUSH 1</span></span>
<span class="line"><span>PRINT</span></span>
<span class="line"><span>JUMP join</span></span>
<span class="line"><span>else_begin:</span></span>
<span class="line"><span>PUSH 2</span></span>
<span class="line"><span>PRINT</span></span>
<span class="line"><span>join:</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>本清单约定条件跳转消费条件。若采用保留条件的指令设计，则两条路径都必须清理它；两种设计都可行，混用才会泄漏栈值。回填函数应接收明确的指令索引，而非修改“最后一条看起来像跳转的指令”，因为嵌套分支会使后者失效。</p><h2 id="循环与短路都依赖控制流" tabindex="-1">循环与短路都依赖控制流 <a class="header-anchor" href="#循环与短路都依赖控制流" aria-label="Permalink to &quot;循环与短路都依赖控制流&quot;">​</a></h2><p>while 的生成顺序是：记录条件起点，生成条件与退出跳转，生成循环体，跳回条件，再回填退出位置。体结束时的栈高度必须等于进入体时，否则每轮会残留临时值。将上例替换为 <code>let x=0; while (x&lt;3) { print(x); x=x+1; } return 0;</code>，预期依次输出 0、1、2。</p><p>短路不能简单翻译为“先计算左右，再 AND”。<code>false &amp;&amp; (1 / 0 == 0)</code> 右侧根本不应执行。正确方向是左边为假直接产生 false，为真才进入右边。对于 <code>||</code>，左边为真就跳过右边。汇合点上两条路径都必须留下一个 bool，且不能多留别的值。</p><p>下面是普通二元表达式的教学片段；短路表达式必须走专门分支：</p><div class="language-cpp vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">void</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> emitBinary</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> BinaryExpr</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> expr</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    emitExpr</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">expr.left);</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    emitExpr</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">expr.right);</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    emit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">opcodeFor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(expr.op));</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>先在纸上列指令，再写生成器，最后看真实 dump。调用还需规定参数的求值顺序与布局；后端必须遵守 Sprout 的规则，不能偶然继承宿主 C++ 某种表达式的求值习惯。</p><h2 id="常见错误与定位" tabindex="-1">常见错误与定位 <a class="header-anchor" href="#常见错误与定位" aria-label="Permalink to &quot;常见错误与定位&quot;">​</a></h2><ul><li>循环只检查一次条件：回边指向体，应该指向条件起点。</li><li>then 结束后接着执行 else：缺少跳过 else 的跳转。</li><li>循环越跑栈越长：语句没有消费临时值，或分支的栈效果不一致。</li><li>嵌套块读错变量：代码生成丢掉了语义分析建立的绑定身份。</li></ul><h2 id="练习、答案与验收" tabindex="-1">练习、答案与验收 <a class="header-anchor" href="#练习、答案与验收" aria-label="Permalink to &quot;练习、答案与验收&quot;">​</a></h2><ol><li>手工生成 <code>(8-2)*(3+1)</code> 并写每步栈内容。</li><li>画出 <code>true || (1/0==0)</code> 的两条路径。</li><li>将循环上界改为 0，再检查空循环行为。</li></ol><details><summary>参考答案</summary><p>第一题依次为 PUSH 8、PUSH 2、SUB、PUSH 3、PUSH 1、ADD、MUL，最终为 24，最大栈高度 3。第二题左边 true 直接跳到得到 true 的路径，不能先执行除法再决定是否使用结果。第三题第一次条件即 false，应直接到循环之后。验收还需覆盖负数减法、嵌套分支和循环中的函数调用。</p></details><h2 id="来源与后续" tabindex="-1">来源与后续 <a class="header-anchor" href="#来源与后续" aria-label="Permalink to &quot;来源与后续&quot;">​</a></h2><p>本地 <code>compilers-resources/projects/code-generator/</code> 提供代码生成任务背景；<code>compilers-resources/material/llvm/LLVM IR Tutorial (2019 LLVM Developers Conference).pdf</code> 第 3—6 页说明 IR 的位置和层次。也可对照 <a href="https://llvm.org/docs/tutorial/MyFirstLanguageFrontend/index.html" target="_blank" rel="noreferrer">LLVM 官方前端教程</a> 观察另一种目标表示。下一章给字节码接上调用帧和运行时。</p>`,35)])])}const u=a(p,[["render",l]]);export{k as __pageData,u as default};
